    "text": "De acordo com o texto 'O tempo da infância e a pressa do mundo adulto', a tese central defendida pelo autor é a de que:",
    "excerpt": "Leia o texto para responder às questões a seguir:\n\nO TEMPO DA INFÂNCIA E A PRESSA DO MUNDO ADULTO\n\nVivemos numa sociedade marcada pela aceleração frenética dos ritmos vitais, onde a pressa e a produtividade tornaram-se réguas que medem o valor das pessoas e das instituições. Na ânsia de preparar as crianças para um futuro marcado pela competitividade, os adultos frequentemente incorrem no equívoco de subtrair-lhes a infância, impondo rotinas fabris com agendas milimetricamente cronometradas. Espera-se que o bebê durma com horário prefixado, que a criança de três anos antecipe o treino de letras em cadernos pautados e que os pequenos abandonem precocemente o faz de conta.\n\nNo entanto, a infância não é antessala nem ensaio geral para a vida adulta. A criança é um ser inteiro, sujeito histórico e de direitos que habita o tempo presente e pesquisa o mundo a partir de seus próprios sentidos, brincadeiras e perguntas originais. Ao contemplar uma fileira de formigas no pátio da creche ou passar minutos vertendo água de um recipiente para outro, a criança não está desperdiçando tempo: está formulando hipóteses científicas, refinando sua sensibilidade e construindo sua humanidade. Respeitar o tempo da infância é um imperativo ético e pedagógico inegociável de quem se compromete com a educação das novas gerações.",
