      "O tempo das crianças pequenas no pátio e nas brincadeiras ao ar livre é um desperdício de tempo que atrasa o raciocínio lógico.",
      "A rotina de creches deve ser inflexível e cronometrada milimetricamente para acostumar a criança ao mercado de trabalho.",
      "O brincar de faz de conta deve ser substituído por exercícios motores de cópia em cadernos pautados."
