    "text": "De acordo com a Base Nacional Comum Curricular (BNCC, 2017), analise as afirmações a seguir: I. A expressão educação \"pré-escolar\", utilizada no Brasil até a década de 1980, expressava o entendimento de que a Educação Infantil era uma etapa anterior, independente e preparatória para a escolarização, que só teria seu começo no Ensino Fundamental. II. Com a promulgação da LDB, em 1996, a Educação Infantil passou a ser parte integrante da Educação Básica, situando-se no mesmo patamar que o Ensino Fundamental e o Ensino Médio. Com a modificação introduzida na LDB anos depois, o acesso ao Ensino Fundamental foi antecipado para os 5 anos de idade e a Educação Infantil passou a atender a faixa etária de zero a 4 anos. III. Embora reconhecida como direito de todas as crianças e dever do Estado, a Educação Infantil passa a ser obrigatória para as crianças de 4 e 5 anos apenas com a Emenda Constitucional n.º 59/2009, que determina a obrigatoriedade da Educação Básica dos 4 aos 17 anos, o que foi fundamental para a garantia do acesso das crianças a essa etapa de escolarização em que educar e cuidar estão profundamente vinculados. É correto o que se afirma em:",
