    "text": "A respeito do trecho \"De um lado, muitos se juntaram a Vini, para discutir não só racismo no futebol, mas na própria sociedade espanhola\" e do contexto em que ele está inserido, analise as proposições que seguem: I. Geralmente, a expressão De um lado vem seguida de Por outro lado, dando sequência às ideias e articulando-as de forma coesa. Apesar de os autores não explicitarem essa segunda expressão, no contexto fica claro que a progressão das ideias dá-se pelo trecho \"Essa atitude era uma resposta à outra\", em que o pronome demonstrativo essa faz referência ao que foi tratado a partir de De um lado, e o pronome indefinido outra assume o papel da expressão ausente Por outro lado, estabelecendo os sentidos para o leitor, sem prejuízos na progressão textual. II. A expressão De um lado só tem sentido se, na sequência, os autores do texto complementarem o raciocínio, introduzindo a expressão Por outro lado. Ao não fazerem isso, os autores comprometeram a progressão do texto, deixando a primeira ideia incompleta e causando prejuízo nos sentidos pretendidos. III. A palavra mas trata-se de uma conjunção adversativa e tem como função, na coesão textual do texto, de contrastar informação de maior peso, prestígio ou importância do que a da oração anterior. É correto o que se afirma em:",
