    "text": "Pinto e Sarmento (1997, p. 25), afirmam que \"[...] não queremos apenas abrir janelas para observar a cidade, mas nos aproximarmos das crianças para melhor compreender suas experiências na e sobre a cidade, onde e como brincam, do que mais gostam e menos gostam do lugar onde moram, enfim, quais os sentidos que atribuem à cidade\". Nesse sentido, analise as afirmações a seguir: I. A criança como agente ativo na construção de significados sobre a cidade: a citação de Pinto e Sarmento destaca a importância de compreender a cidade não apenas como um espaço externo observado, mas como um território significativo para as crianças. Elas atribuem sentidos às experiências que vivem na cidade, sendo, portanto, agentes ativos na interpretação e construção de suas realidades urbanas. II. A relevância das experiências infantis no espaço urbano: ao focar nas preferências, brincadeiras e os sentimentos das crianças em relação ao espaço onde vivem, a citação indica que, na Sociologia da Infância, as crianças não são vistas como seres passivos, mas como indivíduos que interagem com o ambiente urbano de maneiras que refletem suas identidades, desejos e percepções do mundo. III. O papel da cidade na formação da subjetividade infantil: a afirmação também sugere que as crianças atribuem sentidos à cidade, revelando como os espaços urbanos influenciam e moldam suas subjetividades. Esse enfoque está relacionado ao estudo da infância nas ciências sociais, que busca compreender como as condições socioespaciais impactam a formação das identidades infantis e suas experiências cotidianas no espaço urbano. Em relação à participação das crianças nos espaços urbanos das cidades, é correto o que se afirma em:",
