    "text": "Um dos grandes desafios educacionais está relacionado à integração do conhecimento. Nesse contexto, segundo Marcos Cordiolli (2002), ao longo dos anos se criou, “um cenário de intensa confusão, com diferentes interpretações para inter, multi e transdisciplinaridade”. O mesmo autor, a partir da literatura, traz distinções entre elas. Isso posto, associe as colunas: Primeira coluna : 1- Interdisciplinaridade 2- Multidisciplinaridade 3- Transdisciplinaridade Segunda coluna : ( ) Estabelece canais comunicantes, pois um especialista de uma área utiliza saberes de outras disciplinas promovendo diferentes interconexões. ( ) Realiza-se na reunião de especialistas de diferentes áreas ou de atividades de mais de uma área, necessariamente com um viés comum e articulados cooperativamente. ( ) Corresponde à produção ou processo de relações entre saberes, a partir de uma disciplina ou de um tema sem as limitações de domínios ou objetos impostos pela especialização das ciências. Assinale a alternativa com a sequência correta:",
